def min_cut(s):
    n = len(s); pal = [[False] * n for _ in range(n)]; cut = [0] * n
    for j in range(n):
        best = j
        for i in range(j + 1):
            if s[i] == s[j] and (j - i < 2 or pal[i + 1][j - 1]):
                pal[i][j] = True; best = 0 if i == 0 else min(best, cut[i - 1] + 1)
        cut[j] = best
    return cut[-1]

