int minCut(string s) {
    int n = s.size(); vector<vector<char>> p(n, vector<char>(n, 0)); vector<int> cut(n);
    for (int j = 0; j < n; j++) { int best = j; for (int i = 0; i <= j; i++) if (s[i] == s[j] && (j - i < 2 || p[i+1][j-1])) { p[i][j] = 1; best = i == 0 ? 0 : min(best, cut[i-1] + 1); } cut[j] = best; }
    return cut[n - 1];
}
